def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > budget:
                rich_opp += 1
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev['bid'])

    if not alive_opponents:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (25.0 - supply) / 10.0
    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.55
    if no_water_days >= 2:
        danger += 1.2
    elif no_water_days >= 1:
        danger += 0.6
    danger += scarcity * 0.5

    if no_water_days >= 2 or hp <= 2:
        emergency_bid = max(95.0, highest_prev + 2.5, avg_prev + 6.0)
        return min(budget, emergency_bid)

    if supply >= 23:
        base = 18.0
    elif supply >= 20:
        base = 28.0
    elif supply >= 17:
        base = 42.0
    else:
        base = 58.0

    if highest_prev >= 150:
        if hp >= 6 and no_water_days == 0:
            base *= 0.75
        else:
            base = max(base, 88.0)
    elif highest_prev >= 120:
        if hp >= 7 and no_water_days == 0 and supply >= 19:
            base *= 0.82
        else:
            base = max(base, min(highest_prev + 1.5, 84.0))
    elif highest_prev > 0:
        base = max(base, min(highest_prev + 1.5, 78.0))

    if urgent_opp >= 2 and hp >= 6 and no_water_days == 0:
        base *= 0.88
    if rich_opp >= 2 and supply <= 17:
        base += 8.0
    if day >= 8 and budget > DAILY_SALARY * 2:
        base += 6.0

    if danger >= 1.2:
        base = max(base, highest_prev + 2.0, 86.0)
    elif danger >= 0.7:
        base = max(base, min(highest_prev + 1.5, 82.0))

    reserve_target = max(0.0, (10 - day) * 16.0)
    spend_cap = budget - reserve_target
    if spend_cap < 8.0:
        spend_cap = min(budget, 12.0 + 8.0 * danger)
    bid = min(base, budget, max(0.0, spend_cap))

    if bid < 1.0 and budget > 0:
        bid = min(budget, 1.0)

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 50.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 100.0

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], DAILY_SALARY * 0.95)
    elif my_status['hp'] < 7:
        bid = min(my_status['budget'], max(avg_prev * 1.05, 110.0))
    else:
        bid = min(my_status['budget'], max(avg_prev * 0.9, 90.0))

    return float(bid)
